"""Generate the version and compilation date displayed by the About screen."""
from datetime import datetime, timezone
from pathlib import Path
import json
import os
import sys

root = Path(__file__).resolve().parents[1]
version = "v" + (root / "VERSION").read_text().strip()
epoch = os.environ.get("SOURCE_DATE_EPOCH")
date = datetime.fromtimestamp(int(epoch), timezone.utc) if epoch else datetime.now().astimezone()
Path(sys.argv[1]).write_text(
    "/* Generated by build_info.py; do not edit. */\n"
    + "#define CHESS_VERSION " + json.dumps(version) + "\n"
    + "#define CHESS_BUILD_DATE " + json.dumps(date.strftime("%Y-%m-%d")) + "\n"
)
